 elif htn is None:
 unknown.append(("hypertension", 1))

 # A2: Age ≥75 (2) or A: Age 65–74 (1)
 if age is None:
 unknown.append(("age", 2))
 else:
 if age >= 75:
 points += 2
 elif 65 <= age <= 74:
 points += 1

 # D: Diabetes mellitus (1)
 if dm is True:
 points += 1
 elif dm is None:
 unknown.append(("diabetes", 1))

 # S2: Stroke/TIA/thromboembolism (2)
 if stroke_tia_te is True:
 points += 2
 elif stroke_tia_te is None:
 unknown.append(("stroke_tia_thromboembolism", 2))

 # V: Vascular disease (MI, PAD, aortic plaque) (1)
 if vascular_disease is True:
 points += 1
 elif vascular_disease is None:
 unknown.append(("vascular_disease", 1))

 # Sc: Sex category (female = 1)
 if sex_female is True:
 points += 1
 elif sex_female is None:
 unknown.append(("sex_female", 1))

 min_score = points
 max_score = points + sum(w for _, w in unknown)
 return min_score, max_score, [name for name, _ in unknown]


